const renderLinkCard = link => {
  const body = (
    <>
      <span className="home-link-card__title">{link.label}</span>
      <span className="home-link-card__description">{link.description}</span>
    </>
  )

  if (link.to) {
    return (
      <Link key={link.label} className="home-link-card" to={link.to}>
        {body}
      </Link>
    )
  }

  return (
    <a
      key={link.label}
      className="home-link-card"
      href={link.href}
      target={link.href.startsWith("http") ? "_blank" : undefined}
      rel={link.href.startsWith("http") ? "noreferrer" : undefined}
    >
      {body}
    </a>
  )
}

